import { bold, brightGreen, cyan, gray, italic, red, strikethrough, yellow, } from "../deps/colors.js";
const severity = {
    TRACE: 1,
    DEBUG: 5,
    INFO: 9,
    WARN: 13,
    ERROR: 17,
    FATAL: 21,
};
const COLOR_TAG_REG = /<(\w+)>([^<]+)<\/\1>/g;
const logFormats = {
    cyan,
    Cyan: (str) => bold(cyan(str)),
    red,
    Red: (str) => bold(red(str)),
    gray,
    code: gray,
    Gray: (str) => bold(gray(str)),
    green: brightGreen,
    Green: (str) => bold(brightGreen(str)),
    yellow: yellow,
    Yellow: (str) => bold(yellow(str)),
    del: (str) => strikethrough(gray(str)),
    em: italic,
    strong: bold,
};
/**
 * This is the default logger. It will output color coded log messages to the
 * console via `console.log()`.
 */
export default class Logger {
    #level;
    #collection;
    #logs = new Map();
    constructor(level) {
        this.#level = severity[level];
    }
    set collection(collection) {
        this.#collection = collection;
    }
    get level() {
        return this.#level;
    }
    #log(msg, level) {
        if (level >= severity.FATAL) {
            msg = `<Red>FATAL</Red> ${msg}`;
        }
        else if (level >= severity.ERROR) {
            msg = `<red>ERROR</red> ${msg}`;
        }
        else if (level >= severity.WARN) {
            msg = `<yellow>WARN</yellow> ${msg}`;
        }
        msg = msg.replaceAll(COLOR_TAG_REG, (all, name, content) => logFormats[name]?.(content) ?? all);
        if (level <= severity.INFO) {
            console.log(msg);
            return;
        }
        const logs = this.#logs.get(level) ?? new Set();
        this.#logs.set(level, logs);
        if (!logs.has(msg)) {
            logs.add(msg);
            return true;
        }
    }
    get hasErrors() {
        return !!(this.#logs.get(severity.ERROR)?.size || this.#logs.get(severity.FATAL)?.size);
    }
    output() {
        for (const level of Object.values(severity)) {
            const messages = this.#logs.get(level);
            if (!messages) {
                continue;
            }
            if (level >= severity.ERROR) {
                messages.forEach((msg) => console.error(msg));
                continue;
            }
            if (level >= severity.WARN) {
                messages.forEach((msg) => console.warn(msg));
                continue;
            }
            messages.forEach((msg) => console.log(msg));
        }
        this.#logs.clear();
    }
    fatal(msg, items) {
        if (this.#log(msg, severity.FATAL) || items) {
            this.#bar(msg, "fatal", items);
        }
    }
    error(msg, items) {
        if (this.#level < severity.FATAL) {
            if (this.#log(msg, severity.ERROR) || items) {
                this.#bar(msg, "error", items);
            }
        }
    }
    warn(msg, items) {
        if (this.#level < severity.ERROR) {
            if (this.#log(msg, severity.WARN) || items) {
                this.#bar(msg, "warn", items);
            }
        }
    }
    info(msg) {
        if (this.#level < severity.WARN) {
            this.#log(msg, severity.INFO);
        }
    }
    debug(msg) {
        if (this.#level < severity.INFO) {
            this.#log(msg, severity.DEBUG);
        }
    }
    trace(msg) {
        if (this.#level < severity.DEBUG) {
            this.#log(msg, severity.TRACE);
        }
    }
    #bar(message, context, items) {
        const collection = this.#collection;
        if (collection) {
            const [title, ...rest] = message.split("\n");
            const item = {
                context,
                title,
                items: items?.map((item) => (typeof item === "string" ? { title: item } : item)),
            };
            if (rest.length === 1) {
                item.text = rest[0];
            }
            else if (rest.length > 1) {
                item.code = rest.join("\n");
            }
            collection.items.push(item);
        }
    }
}
